#!/data/data/com.termux/files/usr/bin/bash
# The Hunter Ai — Termux Setup v3.0
# Sirf Termux me, ek script: zsh + p10k look + banner, OpenCode (AI coding),
# Java 17 + Android SDK + aapt2, aur phone pe hi ek test APK.

# ─── Colors ─────────────────────────────────────────────────────────
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
PURPLE='\033[0;35m'
RED='\033[0;31m'
BOLD='\033[1m'
NC='\033[0m'

# Jo step fail hua uska naam yahan jaata hai; end me sach bataenge
FAILS=()
ok()   { echo -e "${GREEN}      ✓ $1${NC}"; }
fail() { FAILS+=("$1"); echo -e "${RED}      ✗ $1 fail hua${NC}"; }

# Phone ki screen ~40 column chaudi hoti hai, isliye box 40 ka
box() {
    local bar; bar=$(printf '═%.0s' $(seq 38))
    echo "╔${bar}╗"
    for line in "$@"; do
        if [ "$line" = "--" ]; then echo "╠${bar}╣"; else printf "║ %-36s ║\n" "$line"; fi
    done
    echo "╚${bar}╝"
}

# Versions — ek saath phone pe test kiye hue, inko alag alag mat badalna
SDK_DIR="$HOME/android-sdk"
CMDLINE_ZIP="commandlinetools-linux-11076708_latest.zip"
PLATFORM="android-35"
BUILD_TOOLS="35.0.0"
GRADLE_VER="8.9"
AGP_VER="8.7.3"
KOTLIN_VER="2.0.21"
START=$(date +%s)

clear
echo -e "${PURPLE}${BOLD}"
box "The Hunter Ai - Termux Setup v3.0" -- "OpenCode + Android APK tools" "Internet ~1 GB, time 10-15 min" -- "YouTube : @TheHunter-AI" "Website : getmaya.online"
echo -e "${NC}"
sleep 1

# ─── Banner Name ─────────────────────────────────────────────────────
echo -e "${CYAN}${BOLD}Apna naam likho (banner ke liye):${NC}"
echo -e "${YELLOW}Jaise: Hunter, Rahul, Dev (bina space)${NC}"
echo ""
printf "➜ Your Name: "
read USER_BANNER_NAME
USER_BANNER_NAME="${USER_BANNER_NAME// /}"
[ -z "$USER_BANNER_NAME" ] && USER_BANNER_NAME="Hunter"
echo "$USER_BANNER_NAME" > ~/.hunter_name
ok "Banner set: ${USER_BANNER_NAME}"
echo ""
sleep 1

# ─── Step 1: Storage ─────────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[1/8] Storage access...${NC}"
can_write_sdcard() { touch /sdcard/.hunter_probe 2>/dev/null && rm -f /sdcard/.hunter_probe; }
STORAGE_OK=0
if can_write_sdcard && [ -d ~/storage ]; then
    STORAGE_OK=1    # script dobara chal raha hai: permission pehle se hai, sawaal mat poochho
else
    echo -e "${YELLOW}      Popup aayega → Allow dabao${NC}"
    termux-setup-storage
    for i in $(seq 1 60); do
        if can_write_sdcard; then STORAGE_OK=1; break; fi
        sleep 1
    done
fi
[ "$STORAGE_OK" = 1 ] && ok "Storage mil gaya" || fail "Storage permission (baad me: termux-setup-storage)"

# ─── Step 2: System Update ───────────────────────────────────────────
echo -e "${CYAN}${BOLD}[2/8] System update & upgrade...${NC}"
# Termux khud koi bhi random mirror chunta hai; jo mirror us waqt sync ho raha ho
# us pe "File has unexpected size" aata hai aur update fail. User ne khud mirror
# nahi chuna ho (termux-change-repo) to default wala lagao — Cloudflare, sabse stable.
# (pkg pehle se chuna mirror kuch ghante tak nahi badalta, isliye sources.list bhi seedha likhte hain)
TM="$PREFIX/etc/termux"
if [ ! -e "$TM/chosen_mirrors" ] && [ -f "$TM/mirrors/default" ]; then
    MAIN_URL=$(sed -n 's/^MAIN="\(.*\)"$/\1/p' "$TM/mirrors/default")
    ln -sf "$TM/mirrors/default" "$TM/chosen_mirrors"
    if [ -n "$MAIN_URL" ]; then
        echo "deb $MAIN_URL stable main" > "$PREFIX/etc/apt/sources.list" && ok "Mirror: $MAIN_URL"
    fi
fi
pkg update -y || { sleep 3; pkg update -y; } || fail "pkg update"
# Upgrade ke beech config file wale sawaal (openssl.cnf, bash.bashrc...) aate hain;
# confdef+confold = wahi jo Enter dabane pe hota hai, bas script rukta nahi
apt-get -y -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold full-upgrade \
    && ok "System upgrade" || fail "System upgrade"

# ─── Step 3: Packages ────────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[3/8] Packages: Java 17, Gradle, Node, aapt2...${NC}"
pkg install -y git curl wget unzip nano zsh toilet ruby nodejs openjdk-17 gradle aapt aapt2 apksigner \
    && ok "Packages" || fail "Packages"
gem install lolcat && ok "lolcat" || fail "lolcat"
export JAVA_HOME="$PREFIX/lib/jvm/java-17-openjdk"

# ─── Step 4: Look — font, Oh My Zsh, Powerlevel10k ───────────────────
echo -e "${CYAN}${BOLD}[4/8] Font + Oh My Zsh + Powerlevel10k...${NC}"
mkdir -p ~/.termux
wget -q -O ~/.termux/font.ttf \
  "https://github.com/romkatv/powerlevel10k-media/raw/master/MesloLGS%20NF%20Regular.ttf" \
  && ok "MesloLGS Nerd Font" || fail "Font"

if [ ! -d "$HOME/.oh-my-zsh" ]; then
    sh -c "$(curl -fsSL https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)" "" --unattended >/dev/null
fi
[ -f "$HOME/.oh-my-zsh/oh-my-zsh.sh" ] && ok "Oh My Zsh" || fail "Oh My Zsh"

P10K_DIR="${HOME}/.oh-my-zsh/custom/themes/powerlevel10k"
[ -d "$P10K_DIR" ] || git clone -q --depth=1 https://github.com/romkatv/powerlevel10k.git "$P10K_DIR"
[ -d "$P10K_DIR" ] && ok "Powerlevel10k" || fail "Powerlevel10k"

AS_DIR="${HOME}/.oh-my-zsh/custom/plugins/zsh-autosuggestions"
[ -d "$AS_DIR" ] || git clone -q --depth=1 https://github.com/zsh-users/zsh-autosuggestions "$AS_DIR"
[ -d "$AS_DIR" ] && ok "zsh-autosuggestions" || fail "zsh-autosuggestions"

# The Hunter Ai wala p10k look (lean, 1 line). Apna look pehle se ho to wahi rehta hai.
if [ ! -s ~/.p10k.zsh ]; then
echo '' | base64 -d > ~/.p10k.zsh \
  && ok "p10k look (The Hunter Ai)" || fail "p10k look"
else
    ok "p10k look: tumhara apna (p10k configure wala)"
fi

# ─── Step 5: OpenCode ────────────────────────────────────────────────
# OpenCode ka npm wala Android ko nahi pehchanta (EBADPLATFORM). Uska Linux (glibc) wala
# program Termux ke glibc-runner (grun) se seedha chalta hai — Ubuntu ki zaroorat nahi.
echo -e "${CYAN}${BOLD}[5/8] OpenCode (AI coding)...${NC}"
pkg install -y glibc-repo && pkg install -y glibc-runner && ok "glibc-runner" || fail "glibc-runner"
OC_DIR="$HOME/.opencode/bin"
OC_VER=$(npm view opencode-linux-arm64 version 2>/dev/null); [ -z "$OC_VER" ] && OC_VER="1.19.5"
echo -e "${YELLOW}      OpenCode $OC_VER: ~80 MB download — ruko...${NC}"
mkdir -p "$OC_DIR" && rm -rf "$TMPDIR/oc" && mkdir -p "$TMPDIR/oc" && cd "$TMPDIR/oc" \
  && npm pack --silent "opencode-linux-arm64@$OC_VER" >/dev/null \
  && tar xzf "opencode-linux-arm64-$OC_VER.tgz" \
  && mv -f package/bin/opencode "$OC_DIR/opencode-linux" && chmod +x "$OC_DIR/opencode-linux"
cd "$HOME"; rm -rf "$TMPDIR/oc"
cat > "$PREFIX/bin/opencode" << 'EOF'
#!/data/data/com.termux/files/usr/bin/sh
exec grun "$HOME/.opencode/bin/opencode-linux" "$@"
EOF
chmod +x "$PREFIX/bin/opencode"
OC_V=$(opencode --version 2>/dev/null | head -1)
[ -n "$OC_V" ] && ok "OpenCode $OC_V" || fail "OpenCode"

# ─── Step 6: Android SDK ─────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[6/8] Android SDK (platform 35 + build-tools)...${NC}"
mkdir -p "$SDK_DIR/cmdline-tools"
if [ ! -x "$SDK_DIR/cmdline-tools/latest/bin/sdkmanager" ]; then
    echo -e "${YELLOW}      Command line tools: ~150 MB download — ruko...${NC}"
    cd "$TMPDIR" && wget -q -O cmdline.zip "https://dl.google.com/android/repository/$CMDLINE_ZIP" \
      && rm -rf cmdline-tools && unzip -q cmdline.zip && rm -rf "$SDK_DIR/cmdline-tools/latest" \
      && mv cmdline-tools "$SDK_DIR/cmdline-tools/latest" && rm -f cmdline.zip \
      && ok "Command line tools" || fail "Command line tools"
    cd "$HOME"
fi
SDKM="$SDK_DIR/cmdline-tools/latest/bin/sdkmanager"
yes | "$SDKM" --sdk_root="$SDK_DIR" --licenses >/dev/null 2>&1
# sdkmanager ki progress bar phone ki patli screen pe sau line ka kachra banati hai, isliye chhupao
echo -e "${YELLOW}      ~200 MB download + unzip, 2-5 min — ruko...${NC}"
"$SDKM" --sdk_root="$SDK_DIR" "platforms;$PLATFORM" "build-tools;$BUILD_TOOLS" 2>&1 \
    | grep --line-buffered -vE 'Downloading|Unzipping|^[[:space:]]*$'
# sdkmanager ka apna result dekho (grep ka nahi — saari lines chhupi hon to grep "fail" bolta hai)
SDK_RC=${PIPESTATUS[0]}
[ "$SDK_RC" = 0 ] && [ -d "$SDK_DIR/build-tools/$BUILD_TOOLS" ] \
    && ok "SDK platform + build-tools" || fail "SDK platform + build-tools"
# Google ke build-tools PC (x86) ke liye hain; phone (ARM) pe Termux wale tools lagao
BT="$SDK_DIR/build-tools/$BUILD_TOOLS"
for t in aapt aapt2 aidl zipalign apksigner; do
    if [ -e "$BT/$t" ] && command -v "$t" >/dev/null; then ln -sf "$(command -v $t)" "$BT/$t"; fi
done
[ -f "$SDK_DIR/platforms/$PLATFORM/android.jar" ] && ok "android.jar mila" || fail "android.jar"

mkdir -p ~/.gradle
GP=~/.gradle/gradle.properties
touch "$GP"
sed -i '/^android.aapt2FromMavenOverride=/d;/^org.gradle.jvmargs=/d;/^org.gradle.vfs.watch=/d;/^kotlin.daemon.jvmargs=/d' "$GP"
cat >> "$GP" << EOF
android.aapt2FromMavenOverride=$PREFIX/bin/aapt2
org.gradle.jvmargs=-Xmx2048m -Dfile.encoding=UTF-8
org.gradle.vfs.watch=false
kotlin.daemon.jvmargs=-Xmx1024m
EOF
ok "~/.gradle/gradle.properties (aapt2 = phone wala)"
export ANDROID_HOME="$SDK_DIR" ANDROID_SDK_ROOT="$SDK_DIR"

# ─── Step 7: Test APK ────────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[7/8] Test app ka APK (pehli baar 3-5 min)...${NC}"
APP="$HOME/hello-hunter"
rm -rf "$APP"; mkdir -p "$APP/app/src/main/java/com/hunter/hello"
cat > "$APP/settings.gradle" << 'EOF'
pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }
dependencyResolutionManagement { repositories { google(); mavenCentral() } }
rootProject.name = "HelloHunter"
include(":app")
EOF
cat > "$APP/build.gradle" << EOF
plugins {
    id 'com.android.application' version '$AGP_VER' apply false
    id 'org.jetbrains.kotlin.android' version '$KOTLIN_VER' apply false
}
EOF
cat > "$APP/app/build.gradle" << 'EOF'
plugins {
    id 'com.android.application'
    id 'org.jetbrains.kotlin.android'
}
android {
    namespace 'com.hunter.hello'
    compileSdk 35
    defaultConfig {
        applicationId 'com.hunter.hello'
        minSdk 24
        targetSdk 35
        versionCode 1
        versionName '1.0'
    }
    compileOptions { sourceCompatibility JavaVersion.VERSION_17; targetCompatibility JavaVersion.VERSION_17 }
    kotlinOptions { jvmTarget = '17' }
}
EOF
cat > "$APP/app/src/main/AndroidManifest.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <application android:label="Hello Hunter" android:theme="@android:style/Theme.Material">
        <activity android:name=".MainActivity" android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
    </application>
</manifest>
EOF
cat > "$APP/app/src/main/java/com/hunter/hello/MainActivity.kt" << 'EOF'
package com.hunter.hello

import android.app.Activity
import android.os.Bundle
import android.view.Gravity
import android.widget.TextView

class MainActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(TextView(this).apply {
            text = "Ye app phone pe hi bana hai!"
            textSize = 26f
            gravity = Gravity.CENTER
        })
    }
}
EOF
# Gradle wrapper: khali folder me banao (Termux ka gradle naya hai, project purane AGP wala)
WR="$TMPDIR/wrapper-gen"; rm -rf "$WR"; mkdir -p "$WR" && cd "$WR" && touch settings.gradle \
  && gradle -q wrapper --gradle-version "$GRADLE_VER" && cp -r gradlew gradle "$APP/" \
  && rm -rf ~/.hunter/wrapper && mkdir -p ~/.hunter/wrapper && cp -r gradlew gradle ~/.hunter/wrapper/ \
  && ok "Gradle wrapper $GRADLE_VER" || fail "Gradle wrapper"
cd "$APP"
T0=$(date +%s)
if ./gradlew assembleDebug --no-daemon; then
    APK="$APP/app/build/outputs/apk/debug/app-debug.apk"
    ok "APK bana: $(du -h "$APK" | cut -f1) in $(( $(date +%s) - T0 )) s"
    [ "$STORAGE_OK" = 1 ] && cp "$APK" /sdcard/Download/hello-hunter.apk && ok "Copy: Download/hello-hunter.apk"
else
    fail "Test APK build"
fi
cd "$HOME"

# ─── Step 8: .zshrc + zsh ────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[8/8] .zshrc + zsh...${NC}"
rm -f ~/.cache/p10k-instant-prompt-*.zsh 2>/dev/null
cat > ~/.zshrc << 'STATIC_ZSHRC'
# ═══════════════════════════════════════════════════
#  The Hunter Ai — Termux ZSH Config v3.0
#  YouTube : @TheHunter-AI | getmaya.online
# ═══════════════════════════════════════════════════

# Oh My Zsh
export ZSH="$HOME/.oh-my-zsh"
ZSH_THEME="powerlevel10k/powerlevel10k"
plugins=(git zsh-autosuggestions)
source $ZSH/oh-my-zsh.sh

# ===== ANDROID BUILD =====
export JAVA_HOME=$PREFIX/lib/jvm/java-17-openjdk
export ANDROID_HOME=$HOME/android-sdk
export ANDROID_SDK_ROOT=$ANDROID_HOME
export PATH=$ANDROID_HOME/cmdline-tools/latest/bin:$PATH

# ===== ALIASES =====
alias c='clear'
alias update='pkg update && pkg upgrade'
alias coding='cd /sdcard/coding'
# Naye Android project me gradlew daalo (phir: ./gradlew assembleDebug)
alias addwrapper='cp -r ~/.hunter/wrapper/gradlew ~/.hunter/wrapper/gradle . && echo "gradlew aa gaya"'

# ===== HUNTER BANNER =====
# Bhare hue akshar (smblock) + border, beech me, rainbow colour (lolcat).
# Naam screen se lamba ho to border hata ke chhota.
_hunter_banner() {
  local name w out l p max=0
  name=$(cat ~/.hunter_name 2>/dev/null || echo Hunter)
  w=${COLUMNS:-49}
  out=$(toilet -w 1000 -f smblock -F border "$name")
  while IFS= read -r l; do (( ${#l} > max )) && max=${#l}; done <<< "$out"
  (( max > w )) && out=$(toilet -w "$w" -f smblock "$name")
  echo
  while IFS= read -r l; do
    p=$(( (w - ${#l}) / 2 )); (( p < 0 )) && p=0
    printf "%*s%s\n" "$p" "" "$l"
  done <<< "$out" | lolcat -S 1 -F 0.25 -p 2
}
_hunter_banner
echo
# =========================

# P10k look
[[ ! -f ~/.p10k.zsh ]] || source ~/.p10k.zsh
# Banner zsh khulte waqt print hota hai; instant prompt chalu ho to p10k upar lamba warning dikhata hai.
# p10k configure isko wapas "verbose" kar deta hai, isliye .p10k.zsh ke BAAD off karte hain.
typeset -g POWERLEVEL9K_INSTANT_PROMPT=off
STATIC_ZSHRC
ok ".zshrc"
touch ~/.hushlogin
chsh -s zsh 2>/dev/null && ok "ZSH default shell" || fail "ZSH default shell"
termux-reload-settings 2>/dev/null || true

# ─── Done! ───────────────────────────────────────────────────────────
echo ""
echo -e "${CYAN}Total time: $(( ($(date +%s) - START) / 60 )) min${NC}"
if [ ${#FAILS[@]} -eq 0 ]; then
    echo -e "${GREEN}${BOLD}"
    box "SETUP COMPLETE!" -- \
        "Test APK: Download/hello-hunter.apk" \
        "" \
        "1. Termux band karke kholo" \
        "2. OpenCode se app banwao:" \
        "   cd ~/hello-hunter" \
        "   opencode" \
        "3. APK banao:" \
        "   ./gradlew assembleDebug"
    echo -e "${NC}"
else
    echo -e "${RED}${BOLD}Setup poora nahi hua. Ye fail hue:${NC}"
    for f in "${FAILS[@]}"; do echo -e "${RED}  ✗ $f${NC}"; done
    echo -e "${YELLOW}Internet check karo aur 'bash hunter.sh' dobara chalao — jo ho chuka hai wo skip hoga.${NC}"
fi
